-- ============ Part 2: security (hand-written) ============

-- Application roles: non-superuser, no BYPASSRLS, never table owners.
-- Passwords are NOT set here (no secrets in versioned SQL); see
-- apps/api/prisma/scripts/provision-db-roles.ts, which reads them from env.
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'hrvo_app') THEN
    CREATE ROLE hrvo_app WITH LOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'hrvo_retention') THEN
    CREATE ROLE hrvo_retention WITH LOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
  EXECUTE format('GRANT CONNECT ON DATABASE %I TO hrvo_app, hrvo_retention', current_database());
END
$$;

GRANT USAGE ON SCHEMA public TO hrvo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO hrvo_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO hrvo_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO hrvo_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO hrvo_app;

-- Enable + FORCE RLS and a strict tenant policy on every tenant table.
-- Missing app.org_id => 0 rows; foreign org_id rejected by WITH CHECK.
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'users', 'teams', 'work_schedules', 'attendance_sessions', 'attendance_segments',
    'heartbeat_nonces', 'device_sequences', 'session_secrets', 'attendance_corrections',
    'attendance_daily', 'draft_timesheets', 'presence_events', 'audit_logs',
    'monitoring_consents', 'invitations', 'auth_sessions'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;

-- organizations is keyed by id rather than org_id.
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY organizations_org_policy ON organizations
  FOR ALL
  USING (id = NULLIF(current_setting('app.org_id', true), '')::uuid)
  WITH CHECK (id = NULLIF(current_setting('app.org_id', true), '')::uuid);

-- Append-only tables: application role may only INSERT + SELECT (FR-AUD-001).
REVOKE UPDATE, DELETE, TRUNCATE ON audit_logs, presence_events, monitoring_consents FROM hrvo_app;
GRANT SELECT, INSERT ON audit_logs, presence_events, monitoring_consents TO hrvo_app;

-- Dedicated retention role for presence_events pruning (FR-ATT-020).
GRANT USAGE ON SCHEMA public TO hrvo_retention;
GRANT SELECT, DELETE ON presence_events TO hrvo_retention;

-- SECURITY DEFINER lookups: the only controlled entry points for
-- unauthenticated requests that must find a row before tenant context exists.
CREATE FUNCTION fn_lookup_user_for_auth(p_email TEXT)
RETURNS SETOF users
SECURITY DEFINER
SET search_path = public
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM users WHERE LOWER(email) = LOWER(p_email);
END;
$$;

CREATE FUNCTION fn_lookup_invitation_for_signup(p_token_hash VARCHAR)
RETURNS SETOF invitations
SECURITY DEFINER
SET search_path = public
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM invitations WHERE token_hash = p_token_hash;
END;
$$;

CREATE FUNCTION fn_lookup_session_for_refresh(p_token_hash VARCHAR)
RETURNS TABLE (
  id UUID,
  org_id UUID,
  user_id UUID,
  family_id UUID,
  is_revoked BOOLEAN,
  expires_at TIMESTAMPTZ,
  email VARCHAR,
  display_name VARCHAR,
  role VARCHAR,
  team_id UUID
)
SECURITY DEFINER
SET search_path = public
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY
  SELECT s.id, s.org_id, s.user_id, s.family_id, s.is_revoked, s.expires_at,
         u.email, u.display_name, u.role, u.team_id
  FROM auth_sessions s
  JOIN users u ON u.id = s.user_id
  WHERE s.refresh_token_hash = p_token_hash;
END;
$$;

REVOKE ALL ON FUNCTION fn_lookup_user_for_auth(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION fn_lookup_invitation_for_signup(VARCHAR) FROM PUBLIC;
REVOKE ALL ON FUNCTION fn_lookup_session_for_refresh(VARCHAR) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_lookup_user_for_auth(TEXT) TO hrvo_app;
GRANT EXECUTE ON FUNCTION fn_lookup_invitation_for_signup(VARCHAR) TO hrvo_app;
GRANT EXECUTE ON FUNCTION fn_lookup_session_for_refresh(VARCHAR) TO hrvo_app;
